<template><el-container><el-header><el-button @click="router.push('/health-home')">返回首页</el-button><h3>AI咨询</h3></el-header><el-main><el-alert :title="configured?'外部智能体已配置，提交后将调用扣子':'外部AI未配置：当前仅提供固定的本地操作帮助'" :type="configured?'success':'info'" :closable="false"/><el-space class="suggestions"><el-button v-for="s in suggestions" :key="s" @click="question=s">{{s}}</el-button></el-space><el-input v-model="question" type="textarea" maxlength="2000" :rows="4" placeholder="输入问题；请勿输入真实个人病历或敏感信息"/><el-button type="primary" :loading="busy" @click="ask">{{configured?'向智能体提问':'查看本地帮助'}}</el-button><el-button :disabled="!configured" @click="report">生成AI教学报告</el-button><el-card v-for="(m,i) in messages" :key="i"><el-tag>{{m.source}}</el-tag><p>{{m.question}}</p><pre>{{m.answer}}</pre></el-card></el-main></el-container></template>
<script setup>import{ref,onMounted}from'vue';import{useRouter}from'vue-router';import{call}from'@/api/health';import{ElMessage}from'element-plus';const router=useRouter(),configured=ref(false),question=ref(''),messages=ref([]),busy=ref(false),suggestions=ref(['如何查看测量记录？','如何申请在线问询？','如何生成健康报告？']);async function ask(){if(!question.value.trim())return;busy.value=true;try{const d=(await call('ai/consult','post',{question:question.value})).data;messages.value.unshift({...d,question:question.value});suggestions.value=d.followups||[];question.value=''}finally{busy.value=false}}async function report(){await call('ai/report','post');ElMessage.success('AI报告已保存，待健康师审核')}onMounted(async()=>configured.value=(await call('ai/status')).data.configured)</script><style scoped>.el-header{display:flex;align-items:center;gap:24px}.el-main{min-height:90vh;background:#f1f7f6;padding:32px 8vw}.suggestions{margin:24px 0;flex-wrap:wrap}.el-card{margin-top:24px}pre{white-space:pre-wrap;line-height:1.8;font-family:inherit}</style>
